const input = $json.body ?? $json;

const text = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  return ['true', '1', 'yes', 'on'].includes(text(value).toLowerCase());
};

const exception_id = Number(input.exception_id);
const options_per_patient = Number(input.options_per_patient ?? 3);
const search_days = Number(input.search_days ?? 14);
const confirm_prepare = toBoolean(input.confirm_prepare);

const errors = [];

if (!Number.isInteger(exception_id) || exception_id < 1) {
  errors.push({
    field: 'exception_id',
    message: 'exception_id باید یک عدد صحیح بزرگ‌تر از صفر باشد.',
  });
}

if (
  !Number.isInteger(options_per_patient) ||
  options_per_patient < 1 ||
  options_per_patient > 5
) {
  errors.push({
    field: 'options_per_patient',
    message: 'options_per_patient باید یک عدد صحیح بین 1 و 5 باشد.',
  });
}

if (
  !Number.isInteger(search_days) ||
  search_days < 1 ||
  search_days > 60
) {
  errors.push({
    field: 'search_days',
    message: 'search_days باید یک عدد صحیح بین 1 و 60 باشد.',
  });
}

if (confirm_prepare !== true) {
  errors.push({
    field: 'confirm_prepare',
    message: 'آماده‌سازی پرونده‌های تغییر باید به‌صورت صریح تأیید شود.',
  });
}

return [
  {
    json: {
      exception_id,
      options_per_patient,
      search_days,
      confirm_prepare,
      validation_status: errors.length === 0 ? 'valid' : 'invalid',
      errors,
    },
  },
];

return [
  {
    json: {
      success: false,
      result: 'invalid_request',
      message: 'اطلاعات درخواست ناقص یا نامعتبر است.',
      disruption_case_count: 0,
      disruption_cases: [],
      errors: $json.errors ?? [],
    },
  },
];
